import{_ as i,a0 as s,w as r,s as m,ao as l,I as p,x as t,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節  GNOME桌面） | LCTT x X-CMD","titleTemplate":false,"description":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節  GNOME桌面） | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節  GNOME桌面） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節  GNOME桌面） | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 2 - The GNOME Desktop","title":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節  GNOME桌面）","tag":"201508","desc":""},"relativePath":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 2 - The GNOME Desktop.md","filePath":"[post].md"}'),g={name:"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 2 - The GNOME Desktop.md"};function G(h,e,E,d,_,M){const o=s("Link");return r(),m("div",null,[e[11]||(e[11]=l('<h1 id="一週-gnome-之旅-品味它和-kde-的是是非非-第二節-gnome桌面" tabindex="-1">一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節 GNOME桌面） <a class="header-anchor" href="#一週-gnome-之旅-品味它和-kde-的是是非非-第二節-gnome桌面" aria-label="Permalink to “一週 GNOME 之旅：品味它和 KDE 的是是非非（第二節  GNOME桌面）”">​</a></h1><h3 id="桌面" tabindex="-1">桌面 <a class="header-anchor" href="#桌面" aria-label="Permalink to “桌面”">​</a></h3><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_gdm_show&amp;w=1920" alt=""></p><p>在我這一週的前五天中，我都是直接手動登錄進 Gnome 的——沒有打開自動登錄功能。在第五天的晚上，每一次都要手動登錄讓我覺得很厭煩，所以我就到用户管理器中打開了自動登錄功能。下一次我登錄的時候收到了一個提示：“你的密鑰鏈（keychain）未解鎖，請輸入你的密碼解鎖”。在這時我才意識到了什麼……Gnome 以前一直都在自動解鎖我的密鑰鏈（KDE 中叫做我的錢包），每當我通過 GDM 登錄時 ！當我繞開 GDM 的登錄程序時，Gnome 才不得不介入讓我手動解鎖。</p><p>現在，鄙人的陋見是如果你打開了自動登錄功能，那麼你的密鑰鏈也應當自動解鎖——否則，這功能還有何用？無論如何，你還是需要輸入你的密碼，況且在 GDM 登錄界面你還有機會選擇要登錄的會話，如果你想換的話。</p><p>但是，這點且不提，也就是在那一刻，我意識到要讓這桌面感覺就像它在<strong>和我</strong>一起工作一樣是多麼簡單的一件事。當我通過 SDDM 登錄 KDE 時？甚至連啓動界面都還沒加載完成，就有一個窗口彈出來遮擋了啓動動畫（因此啓動動畫也就被破壞了），它提示我解鎖我的 KDE 錢包或 GPG 鑰匙環。</p><p>如果當前還沒有錢包，你就會收到一個創建錢包的提醒——就不能在創建用户的時候同時為我創建一個嗎？接着它又讓你在兩種加密模式中選擇一種，甚至還暗示我們其中一種（Blowfish）是不安全的，既然是為了安全，為什麼還要我選擇一個不安全的東西？作者聲明：如果你安裝了真正的 KDE spin 版本而不是僅僅安裝了被 KDE 搞過的版本，那麼在創建用户時，它就會為你創建一個錢包。但很不幸的是，它不會幫你自動解鎖，並且它似乎還使用了更老的 Blowfish 加密模式，而不是更新而且更安全的 GPG 模式。</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_kgpg_show&amp;w=1920" alt=""></p><p>如果你選擇了那個安全的加密模式（GPG），那麼它會嘗試加載 GPG 密鑰……我希望你已經創建過一個了，因為如果你沒有，那麼你可又要被指責一番了。怎麼樣才能創建一個？額……它不幫你創建一個……也不告訴你怎麼創建……假如你真的搞明白了你應該使用 KGpg 來創建一個密鑰，接着在你就會遇到一層層的菜單和一個個的提示，而這些菜單和提示只能讓新手感到困惑。為什麼你要問我 GPG 的二進制文件在哪？天知道在哪！如果不止一個，你就不能為我選擇一個最新的嗎？如果只有一個，我再問一次，為什麼你還要問我？</p><p>為什麼你要問我要使用多大的密鑰大小和加密算法？你既然默認選擇了 2048 和 RSA/RSA，為什麼不直接使用？如果你想讓這些選項能夠被修改，那就把它們扔在下面的“Expert mode（專家模式）” 按鈕裏去。這裏不僅僅是説讓配置可被用户修改的問題，而是説根本不需要默認把多餘的東西扔在了用户面前。這種問題將會成為這篇文章剩下的主要內容之一……KDE 需要更理智的默認配置。配置是好的，我很喜歡在使用 KDE 時的配置，但它還需要知道什麼時候應該，什麼時候不應該去提示用户。而且它還需要知道“嗯，它是可配置的”不能做為默認配置做得不好的藉口。用户最先接觸到的就是默認配置，不好的默認配置註定要失去用户。</p><p>讓我們拋開密鑰鏈的問題，因為我想我已經表達出了我的想法。</p><hr>',12)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),a(o,{href:"http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=2"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=2",-1)])]),_:1})]),p("p",null,[e[4]||(e[4]=t("作者：Eric Griffith 譯者：",-1)),a(o,{href:"https://github.com/XLCYun"},{default:n(()=>[...e[2]||(e[2]=[t("XLCYun",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[8]||(e[8]=t("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),a(o,{href:"https://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const w=i(g,[["render",G]]);export{k as __pageData,w as default};
